    function register() {
    const username = document.getElementById('username').value;
    const password = document.getElementById('password').value;
    const authStatus = document.getElementById('authStatus');

    if (!username || !password) {
    authStatus.innerHTML = '<span class="error">Please enter username and password</span>';
    return;
}

    fetch('/auth/register', {
    method: 'POST',
    headers: {
    'Content-Type': 'application/json'
},
    body: JSON.stringify({username, password})
})
    .then(response => response.text())
    .then(data => {
    authStatus.innerHTML = '<span class="success">' + data + '</span>';
    document.getElementById('username').value = '';
    document.getElementById('password').value = '';
})
    .catch(error => {
    authStatus.innerHTML = '<span class="error">Registration failed: ' + error + '</span>';
});
}

    function login() {
    const username = document.getElementById('username').value;
    const password = document.getElementById('password').value;
    const authStatus = document.getElementById('authStatus');

    if (!username || !password) {
    authStatus.innerHTML = '<span class="error">Please enter username and password</span>';
    return;
}

    fetch('/auth/login', {
    method: 'POST',
    headers: {
    'Content-Type': 'application/json'
},
    body: JSON.stringify({username, password})
})
    .then(response => response.text())
    .then(token => {
    localStorage.setItem('token', token);
    authStatus.innerHTML = '<span class="success">Login successful! You can now upload documents and ask questions.</span>';
    document.getElementById('username').value = '';
    document.getElementById('password').value = '';
})
    .catch(error => {
    authStatus.innerHTML = '<span class="error">Login failed: ' + error + '</span>';
});
}

    async function uploadFile() {
    try {
    const token = localStorage.getItem('token');
    if (!token) {
    alert('Please login first');
    return;
}
    const file = document.getElementById('fileInput').files[0];
    const formData = new FormData();
    formData.append('file', file);

    const response = await fetch('/doc/upload', {
    method: 'POST',
    body: formData,
    headers: {
    'Authorization': 'Bearer ' + token
}
})

    if (response.ok) {
    document.getElementById('uploadStatus').innerHTML = "Document uploaded successfully";
} else {
    document.getElementById('uploadStatus').innerHTML = "Upload failed";
}
} catch (error) {
    document.getElementById('uploadStatus').innerHTML = error;
}
}

    async function askQuestion() {
    const input = document.getElementById('questionInput');
    const chatBox = document.getElementById('chatBox');
    const question = input.value;
    const token = localStorage.getItem('token');

    if (!token) {
    alert('Please login first');
    return;
}

    input.value = '';

    const userDiv = document.createElement('div');
    userDiv.innerHTML = "<b>You: </b>" + question;
    chatBox.appendChild(userDiv);

    const aiDiv = document.createElement('div');
    aiDiv.innerHTML = "<b>AI: </b>";
    chatBox.appendChild(aiDiv);

    const response = await fetch('/doc/ask?question=' + encodeURIComponent(question), {
    method: 'POST',
    headers: {
    'Authorization': 'Bearer ' + token,
    'userId': extractUserFromToken(token)
}
});

    const reader = response.body.getReader();
    const decoder = new TextDecoder();

    let buffer = "";
    let aiText = "";

    while (true) {
    const {done, value} = await reader.read();
    if (done)
    break;
    buffer += decoder.decode(value, {stream: true});
    let lines = buffer.split("\n");
    buffer = lines.pop();

    for (let line of lines) {
    if (line.startsWith("data:")) {
    const chunk = line.replace("data:", "");
    aiText += chunk;
    aiDiv.innerHTML = "<b>AI:</b>" + aiText;
}
    chatBox.scrollTop = chatBox.scrollHeight;
}
}

    aiDiv.innerHTML = "<b>AI:</b>" + markdownToHtml(aiText);
}

    function extractUserFromToken(token) {
    const payload = token.split('.')[1];
    const decoded = JSON.parse(atob(payload));
    return decoded.sub || decoded.username;
}

    function markdownToHtml(text) {
    return text
    .replace(/\*\*(.*?)\*\*/g, "<b>$1</b>")
    .replace(/\*(.*?)\n/g, "<li>$1</li>")
    .replace(/\+(.*?)\n/g, "<li>$1</li>")
    .replace(/\n/g, "<br>");
}

function register() {
    const username = document.getElementById('username').value;
    const password = document.getElementById('password').value;
    const authStatus = document.getElementById('authStatus');

    if (!username || !password) {
        authStatus.innerHTML = '<div class="alert-custom error p-2 mb-2">Please enter username and password</div>';
        return;
    }

    fetch('/auth/register', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({username, password})
    })
        .then(response => response.text())
        .then(data => {
            authStatus.innerHTML = '<div class="alert-custom success p-2 mb-2">' + data + '</div>';
            document.getElementById('username').value = '';
            document.getElementById('password').value = '';
        })
        .catch(error => {
            authStatus.innerHTML = '<div class="alert-custom error p-2 mb-2">Registration failed: ' + error + '</div>';
        });
}

